mapper.select:
SELECT sur.*, ( SELECT max(fc.company_full_name) FROM fnd_company fc WHERE fc.company_code = sur.company_rule ) AS companyFullName, ( SELECT fop.position_name FROM fnd_org_position fop,fnd_org_unit fou,fnd_company fc WHERE fop.position_code = sur.position_rule and fop.unit_id=fou.unit_id AND fou.unit_code = sur.org_unit_rule and fc.company_id = fou.company_id and fc.company_code = sur.company_rule ) position_name, ( SELECT fou.unit_name FROM fnd_org_unit fou,fnd_company fc WHERE fou.unit_code = sur.org_unit_rule and fc.company_id = fou.company_id and fc.company_code = sur.company_rule ) unit_name FROM sys_user_authority_rule sur, sys_user_allocation sua
1=1 and sur.allocation_id = sua.allocation_id and sur.allocation_id =#{allocationId}
and sur.document_category = #{documentCategory}
ORDER BY sur.authority_rule_id DESC
